var gameUser=function(n){return{updateSpin:function(){confirm("Your are going to update member spins. Are you sure?")&&n.ajax({method:"POST",url:"/GameUser/UpdateSpin",dataType:"json",data:n("#updateSpin").serialize()}).done(function(t){t&&n("#updateModal").modal("hide")})},showUpdateSpinForm:function(t){n.ajax({method:"GET",url:"/GameUser/UpdateSpin?memberId="+t}).done(function(t){t&&(n("#updateSpinContent").html(t),n("#updateModal").modal("show"))})}}}(jQuery);